import { createContext, type RouterContextProvider } from "react-router";

import type { Viewer } from "~/lib/people.server";

export const cloudflareContext = createContext<{ env: Env; ctx: ExecutionContext }>();

/** Set by the gate before any route runs. A route never sees a request without one. */
export const viewerContext = createContext<Viewer>();

/**
 * This render's CSP nonce. It must exist before the render: the same value goes in the header and on
 * every <script>. Set by workers/app.ts; the root loader hands it to Layout.
 */
export const nonceContext = createContext<string>();

export function getNonce(context: Readonly<RouterContextProvider>): string {
  return context.get(nonceContext);
}

export function getEnv(context: Readonly<RouterContextProvider>): Env {
  return context.get(cloudflareContext).env;
}

export function getViewer(context: Readonly<RouterContextProvider>): Viewer {
  return context.get(viewerContext);
}

app/lib/mcp/access-login.ts.source:
// The upstream login for the AI door: Cloudflare Access for SaaS, as an OIDC provider (Cloudflare's
// "Secure MCP servers" doc, developers.cloudflare.com/cloudflare-one/access-controls/ai-controls/
// secure-mcp-servers). Carrel is the OAuth authorization server for MCP clients (door.ts); it does not
// know who the person is, so it sends them to Access, which signs them in with the team's login and
// returns an ID token whose email Carrel maps to its people table.
//
// Every endpoint is derived from the team domain and the SaaS app's client id, as the Access
// dashboard shows them, so the only settings are the two secrets. Fails closed: a missing setting
// keeps the door shut.

import { createRemoteJWKSet, jwtVerify, type JWTVerifyGetKey } from "jose";

import { teamIssuer } from "~/lib/access.server";

export type AccessSaas = {
  clientId: string;
  clientSecret: string;
  /** The SaaS app's issuer: https://<team>.cloudflareaccess.com/cdn-cgi/access/sso/oidc/<client id> */
  issuer: string;
  authorizationUrl: string;
  tokenUrl: string;
  jwksUrl: string;
};

/** The Access for SaaS app's endpoints, or null while any setting is missing. */
export function accessSaas(env: Env): AccessSaas | null {
  const team = env.ACCESS_TEAM_DOMAIN?.trim();
  const clientId = env.ACCESS_SAAS_CLIENT_ID?.trim();
  const clientSecret = env.ACCESS_SAAS_CLIENT_SECRET?.trim();
  if (!team || !clientId || !clientSecret) return null;
  const issuer = `${teamIssuer(team)}/cdn-cgi/access/sso/oidc/${encodeURIComponent(clientId)}`;
  return { clientId, clientSecret, issuer, authorizationUrl: `${issuer}/authorization`, tokenUrl: `${issuer}/token`, jwksUrl: `${issuer}/jwks` };
}

const remoteKeys = new Map<string, JWTVerifyGetKey>();

function keysFor(saas: AccessSaas): JWTVerifyGetKey {
  let keys = remoteKeys.get(saas.jwksUrl);
  if (!keys) {
    keys = createRemoteJWKSet(new URL(saas.jwksUrl));
    remoteKeys.set(saas.jwksUrl, keys);
  }
  return keys;
}

async function s256(verifier: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier));
  return btoa(String.fromCharCode(...new Uint8Array(digest))).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

/** A fresh PKCE verifier and OIDC nonce for one sign-in. Kept server-side by beginUpstream. */
export function newSignIn(): { verifier: string; nonce: string } {
  return { verifier: `${crypto.randomUUID()}${crypto.randomUUID()}`.replace(/-/g, ""), nonce: crypto.randomUUID() };
}

/** Where the browser goes to sign in with Access. */
export async function authorizationUrl(saas: AccessSaas, input: { redirectUri: string; state: string; verifier: string; nonce: string }): Promise<string> {
  const url = new URL(saas.authorizationUrl);
  url.searchParams.set("client_id", saas.clientId);
  url.searchParams.set("redirect_uri", input.redirectUri);
  url.searchParams.set("response_type", "code");
  url.searchParams.set("scope", "openid email profile");
  url.searchParams.set("state", input.state);
  url.searchParams.set("nonce", input.nonce);
  url.searchParams.set("code_challenge", await s256(input.verifier));
  url.searchParams.set("code_challenge_method", "S256");
  return url.href;
}

export type SignedIn = { ok: true; email: string } | { ok: false; reason: string };

/**
 * Exchanges Access's code for tokens and verifies the ID token: signed by the SaaS app's keys, issued
 * by it, for this client, carrying the nonce this sign-in sent, and naming an email. Anything else is
 * a refusal.
 */
export async function finishSignIn(
  saas: AccessSaas,
  input: { code: string; redirectUri: string; verifier: string; nonce: string },
  keys: JWTVerifyGetKey = keysFor(saas),
): Promise<SignedIn> {
  const response = await fetch(saas.tokenUrl, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
    body: new URLSearchParams({
      grant_type: "authorization_code",
      code: input.code,
      redirect_uri: input.redirectUri,
      client_id: saas.clientId,
      client_secret: saas.clientSecret,
      code_verifier: input.verifier,
    }),
  });
  if (!response.ok) return { ok: false, reason: `token-exchange-${response.status}` };
  const tokens = (await response.json().catch(() => ({}))) as { id_token?: unknown };
  if (typeof tokens.id_token !== "string") return { ok: false, reason: "no-id-token" };

  let payload;
  try {
    ({ payload } = await jwtVerify(tokens.id_token, keys, { issuer: saas.issuer, audience: saas.clientId, algorithms: ["RS256"] }));
  } catch {
    return { ok: false, reason: "invalid-id-token" };
  }
  if (payload.nonce !== input.nonce) return { ok: false, reason: "nonce-mismatch" };
  if (payload.email_verified === false) return { ok: false, reason: "email-not-verified" };
  const email = typeof payload.email === "string" ? payload.email.trim() : "";
  if (!email) return { ok: false, reason: "no-email" };
  return { ok: true, email };
}

app/lib/novels/voice.ts.source:
// The voice check's measure (design section 5): sentence length, function-word and punctuation
// profiles of a scene compared with Dustin's own passages in shared/voice/. A distance in the manner
// of Burrows' Delta: each feature's distance from the passages' mean in their standard deviations,
// averaged. It flags only; statistics cannot say whose prose it is, only that it reads unlike his.

const FUNCTION_WORDS = [
  "the", "and", "of", "to", "a", "in", "that", "it", "was", "he", "she", "i", "you", "with", "for", "on", "as",
  "at", "but", "had", "his", "her", "not", "be", "is", "they", "by", "from", "this", "so", "all", "were", "there",
  "which", "would", "when", "then", "what", "if", "into", "out", "up", "like", "just", "some", "no", "one", "or",
];

/** "sentence length", a punctuation mark per 1,000 words, or a quoted function word per 1,000 words. */
type FeatureName = string;

export type Features = Record<FeatureName, number>;

/** How far a passage needs to be before its profile means anything. */
export const MIN_WORDS = 250;
/** The chunk size the baseline passages are cut into, so their spread can be measured. */
const CHUNK_WORDS = 300;
/** The most one feature can add to the distance, in standard deviations. */
const MAX_Z = 5;
/** A floor on sentence length's spread, relative to its mean, so passages that agree closely cannot make it dominate. */
const MIN_SPREAD = 0.15;

function words(text: string): string[] {
  return text.toLowerCase().match(/[\p{L}]+(?:['\u2019][\p{L}]+)*/gu) ?? [];
}

function sentences(text: string): string[] {
  return text
    .replace(/\s+/g, " ")
    .split(/(?<=[.!?])["\u201d\u2019)]?\s+(?=["\u201c\u2018(]?[\p{Lu}\d])/u)
    .map((s) => s.trim())
    .filter((s) => words(s).length > 0);
}

function per1000(count: number, total: number): number {
  return total === 0 ? 0 : (count * 1000) / total;
}

export function features(text: string): Features {
  const all = words(text);
  const total = all.length;
  const sents = sentences(text);
  const counts = new Map<string, number>();
  for (const w of all) counts.set(w, (counts.get(w) ?? 0) + 1);
  const count = (re: RegExp) => text.match(re)?.length ?? 0;

  const out = {
    "sentence length": sents.length === 0 ? 0 : total / sents.length,
    commas: per1000(count(/,/g), total),
    semicolons: per1000(count(/;/g), total),
    colons: per1000(count(/:/g), total),
    dashes: per1000(count(/\u2014|\u2013|--/g), total),
    questions: per1000(count(/\?/g), total),
    exclamations: per1000(count(/!/g), total),
  } as Features;
  for (const fw of FUNCTION_WORDS) out[`"${fw}"`] = per1000(counts.get(fw) ?? 0, total);
  return out;
}

export type Profile = { mean: Features; spread: Features; chunks: number; words: number };

/** Cuts text into runs of about CHUNK_WORDS words, on paragraph boundaries where it can. */
function chunks(text: string): string[] {
  const paragraphs = text.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);
  const out: string[] = [];
  let current: string[] = [];
  let size = 0;
  for (const p of paragraphs) {
    current.push(p);
    size += words(p).length;
    if (size >= CHUNK_WORDS) {
      out.push(current.join("\n\n"));
      current = [];
      size = 0;
    }
  }
  if (size >= CHUNK_WORDS / 2) out.push(current.join("\n\n"));
  return out;
}

/** The profile of Dustin's passages, or null when there is too little of his text to compare with. */
export function profileOf(passages: string[]): Profile | null {
  const pieces = passages.flatMap(chunks);
  if (pieces.length < 3) return null;
  const rows = pieces.map(features);
  const names = Object.keys(rows[0]!) as FeatureName[];
  const mean = {} as Features;
  const spread = {} as Features;
  for (const name of names) {
    const values = rows.map((r) => r[name] ?? 0);
    const m = values.reduce((a, b) => a + b, 0) / values.length;
    const variance = values.reduce((a, b) => a + (b - m) ** 2, 0) / (values.length - 1);
    mean[name] = m;
    // A spread of zero would make any difference infinitely far. A rate cannot be measured finer
    // than one occurrence in a chunk, so that is its floor; sentence length gets a relative one.
    const floor = name === "sentence length" ? MIN_SPREAD * Math.max(1, m) : 1000 / CHUNK_WORDS;
    spread[name] = Math.max(Math.sqrt(variance), floor);
  }
  return { mean, spread, chunks: pieces.length, words: passages.reduce((n, p) => n + words(p).length, 0) };
}

export type VoiceReading = {
  distance: number;
  /** The features furthest from the passages, with the scene's value and the passages' mean. */
  furthest: { name: FeatureName; value: number; mean: number; z: number }[];
};

export function distanceFrom(profile: Profile, text: string): VoiceReading | null {
  if (words(text).length < MIN_WORDS) return null;
  const f = features(text);
  const scored = Object.keys(profile.mean).map((name) => {
    const value = f[name] ?? 0;
    const mean = profile.mean[name] ?? 0;
    return { name, value, mean, z: (value - mean) / (profile.spread[name] ?? 1) };
  });
  // Each feature counts for at most MAX_Z, so one habit (a single semicolon where the passages have
  // none) cannot outweigh everything else.
  const distance = scored.reduce((a, s) => a + Math.min(MAX_Z, Math.abs(s.z)), 0) / scored.length;
  const furthest = [...scored].sort((a, b) => Math.abs(b.z) - Math.abs(a.z)).slice(0, 3);
  return { distance, furthest };
}

/**
 * Where a scene counts as reading unlike the passages. Set between the fixtures in test/voice.test.ts
 * (measured 2026-09-27: the baseline's own passages 0.45 to 0.54, the same register not in the
 * baseline 0.76, a public-domain passage by Henry James 1.49). Recalibrate once shared/voice/ holds
 * Dustin's own text: the test fixtures stand in for it.
 */
export const VOICE_THRESHOLD = 1.1;

export function describeFeature(f: VoiceReading["furthest"][number]): string {
  const round = (n: number) => (n >= 10 ? Math.round(n) : Math.round(n * 10) / 10);
  if (f.name === "sentence length") return `sentences average ${round(f.value)} words against ${round(f.mean)} in your passages`;
  return `${round(f.value)} ${f.name} per 1,000 words against ${round(f.mean)}`;
}

app/lib/social/platforms.server.ts.source:
// The two platforms Carrel posts to, and the one way out to them. There is no reply or direct-message
// code (design section 5, "Social"), and a guard makes sure none can be reached: every request is
// checked against an allowlist of the exact endpoints that create a session or an original post,
// and a post body carrying a reply reference is refused before it is sent.
//
// Bluesky: carried over from legacy Recova's lib/social/bluesky.ts (app-password session reused for
// two hours, createRecord for the post), with its reply and search functions dropped and the session
// kept per account. X: OAuth 1.0a user context for POST /2/tweets, signed here with Web Crypto
// instead of Recova's twitter-api-v2 package.

type Fetch = typeof fetch;

export type Platform = "bluesky" | "x";

export type Credentials =
  | { platform: "bluesky"; handle: string; appPassword: string }
  | { platform: "x"; apiKey: string; apiSecret: string; accessToken: string; accessSecret: string };

/** A refusal made before anything is sent: a reply, a message, or any endpoint not on the list. */
export class SocialRefused extends Error {
  constructor(message: string) {
    super(message);
    this.name = "SocialRefused";
  }
}

const BSKY = "https://bsky.social/xrpc";
const X_TWEETS = "https://api.x.com/2/tweets";

const ALLOWED = new Set([`POST ${BSKY}/com.atproto.server.createSession`, `POST ${BSKY}/com.atproto.repo.createRecord`, `POST ${X_TWEETS}`]);

/** The guard every request passes. Exported so the tests can plant against it directly. */
export function assertOriginalPost(method: string, url: string, body: unknown): void {
  if (!ALLOWED.has(`${method.toUpperCase()} ${url}`)) throw new SocialRefused(`${method} ${url} is not an original post; Carrel never replies, messages, follows or likes.`);
  const b = body as Record<string, unknown> | undefined;
  const record = b?.record as Record<string, unknown> | undefined;
  if (record && (record.reply !== undefined || record.$type !== "app.bsky.feed.post")) throw new SocialRefused("A Bluesky record that is a reply, or not a post, is refused.");
  if (b?.collection !== undefined && b.collection !== "app.bsky.feed.post") throw new SocialRefused(`Writing to ${String(b.collection)} is refused; only posts.`);
  if (url === X_TWEETS && (b?.reply !== undefined || b?.quote_tweet_id !== undefined || b?.direct_message_deep_link !== undefined)) {
    throw new SocialRefused("An X post that replies, quotes or links a direct message is refused.");
  }
}

async function send(fetcher: Fetch, method: string, url: string, body: unknown, headers: Record<string, string> = {}): Promise<Response> {
  assertOriginalPost(method, url, body);
  return fetcher(url, { method, headers: { "Content-Type": "application/json", ...headers }, body: JSON.stringify(body) });
}

// ---------- Bluesky (from Recova)

const bskySessions = new Map<string, { accessJwt: string; did: string; expiresAt: number }>();

export function clearBlueskySessions(): void {
  bskySessions.clear();
}

async function blueskySession(creds: Extract<Credentials, { platform: "bluesky" }>, fetcher: Fetch, now: number) {
  const cached = bskySessions.get(creds.handle);
  // Re-authenticate when missing or within five minutes of expiry (Recova's rule).
  if (cached && now < cached.expiresAt - 5 * 60 * 1000) return cached;
  const res = await send(fetcher, "POST", `${BSKY}/com.atproto.server.createSession`, { identifier: creds.handle, password: creds.appPassword });
  if (!res.ok) throw new Error(`Bluesky sign-in ${res.status}`);
  const data = (await res.json()) as { accessJwt: string; did: string };
  // Bluesky access tokens last two hours.
  const session = { accessJwt: data.accessJwt, did: data.did, expiresAt: now + 2 * 60 * 60 * 1000 };
  bskySessions.set(creds.handle, session);
  return session;
}

/** Bluesky counts graphemes, not UTF-16 units. */
export function graphemes(text: string): number {
  return [...new Intl.Segmenter("en", { granularity: "grapheme" }).segment(text)].length;
}

async function postToBluesky(creds: Extract<Credentials, { platform: "bluesky" }>, text: string, fetcher: Fetch, now: number): Promise<string> {
  const session = await blueskySession(creds, fetcher, now);
  // A link is made clickable with a facet over its byte range, as the app does.
  const facets = [...text.matchAll(/https?:\/\/[^\s]+/g)].map((m) => {
    const start = new TextEncoder().encode(text.slice(0, m.index)).length;
    return {
      index: { byteStart: start, byteEnd: start + new TextEncoder().encode(m[0]).length },
      features: [{ $type: "app.bsky.richtext.facet#link", uri: m[0] }],
    };
  });
  const res = await send(
    fetcher,
    "POST",
    `${BSKY}/com.atproto.repo.createRecord`,
    {
      repo: session.did,
      collection: "app.bsky.feed.post",
      record: { $type: "app.bsky.feed.post", text, createdAt: new Date(now).toISOString(), ...(facets.length ? { facets } : {}) },
    },
    { Authorization: `Bearer ${session.accessJwt}` },
  );
  if (!res.ok) throw new Error(`Bluesky post ${res.status}`);
  return ((await res.json()) as { uri: string }).uri;
}

// ---------- X (OAuth 1.0a, Web Crypto)

/** RFC 3986 percent-encoding, which OAuth 1.0a requires (encodeURIComponent leaves !'()* alone). */
export function percentEncode(value: string): string {
  return encodeURIComponent(value).replace(/[!'()*]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`);
}

/**
 * The OAuth 1.0a HMAC-SHA1 signature. Body parameters are signed only for form bodies; X's v2 JSON
 * body is not part of the base string.
 */
export async function oauthSignature(
  method: string,
  url: string,
  params: Record<string, string>,
  consumerSecret: string,
  tokenSecret: string,
): Promise<string> {
  const normalized = Object.entries(params)
    .map(([k, v]) => [percentEncode(k), percentEncode(v)] as const)
    .sort(([a, av], [b, bv]) => (a < b ? -1 : a > b ? 1 : av < bv ? -1 : av > bv ? 1 : 0))
    .map(([k, v]) => `${k}=${v}`)
    .join("&");
  const base = [method.toUpperCase(), percentEncode(url), percentEncode(normalized)].join("&");
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(`${percentEncode(consumerSecret)}&${percentEncode(tokenSecret)}`), { name: "HMAC", hash: "SHA-1" }, false, ["sign"]);
  const sig = new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(base)));
  let binary = "";
  for (const b of sig) binary += String.fromCharCode(b);
  return btoa(binary);
}

async function postToX(creds: Extract<Credentials, { platform: "x" }>, text: string, fetcher: Fetch, now: number): Promise<string> {
  const nonceBytes = crypto.getRandomValues(new Uint8Array(16));
  const oauth: Record<string, string> = {
    oauth_consumer_key: creds.apiKey,
    oauth_nonce: [...nonceBytes].map((b) => b.toString(16).padStart(2, "0")).join(""),
    oauth_signature_method: "HMAC-SHA1",
    oauth_timestamp: String(Math.floor(now / 1000)),
    oauth_token: creds.accessToken,
    oauth_version: "1.0",
  };
  oauth.oauth_signature = await oauthSignature("POST", X_TWEETS, oauth, creds.apiSecret, creds.accessSecret);
  const header = `OAuth ${Object.entries(oauth)
    .map(([k, v]) => `${percentEncode(k)}="${percentEncode(v)}"`)
    .join(", ")}`;
  const res = await send(fetcher, "POST", X_TWEETS, { text }, { Authorization: header });
  if (!res.ok) throw new Error(`X post ${res.status}`);
  return ((await res.json()) as { data: { id: string } }).data.id;
}

/** The only exported way to post: an original post, text only. There is no reply parameter to pass. */
export async function postOriginal(creds: Credentials, text: string, fetcher: Fetch = fetch, now = Date.now()): Promise<string> {
  return creds.platform === "bluesky" ? postToBluesky(creds, text, fetcher, now) : postToX(creds, text, fetcher, now);
}

/** X's price per post since February 2026 (design section 5), in mills: $0.015, or $0.20 with a link. */
export function xCostMills(text: string): number {
  return /https?:\/\//.test(text) ? 200 : 15;
}

/** Credentials from secrets named for the account key: SOCIAL_<KEY>_..., dashes as underscores. */
export function credentialsFor(env: Env, account: { key: string; platform: Platform; handle: string }): Credentials | { missing: string[] } {
  const prefix = `SOCIAL_${account.key.toUpperCase().replace(/-/g, "_")}_`;
  const get = (name: string) => (env as unknown as Record<string, string | undefined>)[`${prefix}${name}`]?.trim() || "";
  if (account.platform === "bluesky") {
    const appPassword = get("BLUESKY_APP_PASSWORD");
    return appPassword ? { platform: "bluesky", handle: account.handle, appPassword } : { missing: [`${prefix}BLUESKY_APP_PASSWORD`] };
  }
  const names = ["X_API_KEY", "X_API_SECRET", "X_ACCESS_TOKEN", "X_ACCESS_SECRET"];
  const missing = names.filter((n) => !get(n)).map((n) => `${prefix}${n}`);
  if (missing.length) return { missing };
  return { platform: "x", apiKey: get("X_API_KEY"), apiSecret: get("X_API_SECRET"), accessToken: get("X_ACCESS_TOKEN"), accessSecret: get("X_ACCESS_SECRET") };
}

