// Work waiting on a person that the site does not know yet: an AI draft for a new slug is listed in
// the project's Posts, opens in the editor and previews as the AI draft; an indexed post carries a
// count of AI drafts waiting. All of it private to the person the drafts belong to.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { saveAiDraft } from "~/lib/ai.server";
import { autosave } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { refreshIndex } from "~/lib/index.server";
import { requireSiteProject } from "~/lib/projects.server";
import { titleOf } from "~/lib/waiting.server";
import { loader as editorLoader } from "~/routes/editor";
import { loader as previewLoader } from "~/routes/preview";
import { loader as projectLoader } from "~/routes/project";

import { addPerson, addProject, resetDb, share } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
let site: ReturnType<typeof fakeSite>;
let env: Env;
let projectId: number;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

async function aiDraft(email: string, item: string, source: string) {
  const viewer = await viewerFor(email);
  const project = await requireSiteProject(env.DB, viewer, SLUG, "edit");
  await saveAiDraft(env, project, { viewer, client: "Claude" }, item, { source });
}

async function list(email: string, query = "") {
  const request = new Request(`https://carrel.test/p/${SLUG}${query}`);
  return (await projectLoader({ request, params: { project: SLUG }, context: await context(email) } as never)).items;
}

const NEW_POST = "---\ntitle: A desk apart\n---\nWords for a new post.\n";

describe("the project's Posts list", () => {
  it("lists an AI draft for a post the site does not have, and its editor opens", async () => {
    await aiDraft("owner@test.invalid", "a-desk-apart", NEW_POST);
    const items = await list("owner@test.invalid");
    expect(items).toHaveLength(1);
    expect(items[0]).toMatchObject({ itemId: "a-desk-apart", title: "A desk apart", status: "draft", isNew: true, aiDrafts: 1 });

    const page = await editorLoader({ params: { project: SLUG, item: "a-desk-apart" }, context: await context("owner@test.invalid") } as never);
    expect(page.source).toBe("");
    expect(page.aiDrafts).toHaveLength(1);
  });

  it("includes it under the Draft filter and the search, and leaves it out of Published and a kind", async () => {
    await aiDraft("owner@test.invalid", "a-desk-apart", NEW_POST);
    expect(await list("owner@test.invalid", "?status=draft")).toHaveLength(1);
    expect(await list("owner@test.invalid", "?q=desk")).toHaveLength(1);
    expect(await list("owner@test.invalid", "?q=elephant")).toHaveLength(0);
    expect(await list("owner@test.invalid", "?status=published")).toHaveLength(0);
    expect(await list("owner@test.invalid", "?kind=post")).toHaveLength(0);
  });

  it("lists a draft of the person's own for a new post too", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(env.DB, owner, SLUG, "edit");
    await autosave(env.DB, project, owner, "mine", { source: "---\ntitle: Mine\n---\nx\n", baseVersion: null });
    const items = await list("owner@test.invalid");
    expect(items[0]).toMatchObject({ itemId: "mine", title: "Mine", isNew: true, ownDraft: true, aiDrafts: 0 });
  });

  it("marks an indexed post that has AI drafts waiting, with the count", async () => {
    const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Post one\n---\nOn the site.\n", expectedVersion: null, changeId: "s" });
    expect(saved.version).toBeTruthy();
    await refreshIndex(env, { id: projectId, site: "dustinedwards" });
    await aiDraft("owner@test.invalid", "post-one", "A better take.");
    await aiDraft("owner@test.invalid", "post-one", "Another take.");
    const items = await list("owner@test.invalid");
    expect(items).toHaveLength(1);
    expect(items[0]).toMatchObject({ itemId: "post-one", isNew: false, aiDrafts: 2 });
  });

  it("PLANT: shows nobody else's AI drafts, and the editor of one still answers 404", async () => {
    await aiDraft("editor@test.invalid", "a-desk-apart", NEW_POST);
    expect(await list("owner@test.invalid")).toHaveLength(0);
    await expect(editorLoader({ params: { project: SLUG, item: "a-desk-apart" }, context: await context("owner@test.invalid") } as never)).rejects.toMatchObject({ status: 404 });
  });
});

describe("the preview of an AI-draft-only post", () => {
  it("renders the AI draft through the site, labelled as an AI draft", async () => {
    await aiDraft("owner@test.invalid", "a-desk-apart", NEW_POST);
    const request = new Request(`https://carrel.test/p/${SLUG}/e/a-desk-apart/preview`);
    const response = (await previewLoader({ request, params: { project: SLUG, item: "a-desk-apart" }, context: await context("owner@test.invalid") } as never)) as Response;
    const html = await response.text();
    expect(html).toContain("A desk apart");
    expect(html).toContain("AI draft from Claude. It is not your draft and it is not on the site.");
  });

  it("still says there is nothing to preview when there is no AI draft either", async () => {
    const request = new Request(`https://carrel.test/p/${SLUG}/e/none/preview`);
    const response = (await previewLoader({ request, params: { project: SLUG, item: "none" }, context: await context("owner@test.invalid") } as never)) as Response;
    expect(await response.text()).toContain("There is nothing to preview yet.");
  });
});

describe("titleOf", () => {
  it("reads a plain or quoted frontmatter title, and nothing when there is none", () => {
    expect(titleOf("---\ntitle: Plain\n---\nx")).toBe("Plain");
    expect(titleOf('---\ntitle: "Quoted: yes"\n---\nx')).toBe("Quoted: yes");
    expect(titleOf("No frontmatter\ntitle: nope")).toBe("");
  });
});

test/kinds.test.ts.source:
// Every kind the site reports, end to end through the routes: a non-post kind lists under its own
// kind and filter, opens, saves, previews, publishes and shows its revisions exactly as a post does,
// and a data kind the site will not write stays out of the lists and, if reached, shows the site's
// own refusal. Carrel has no per-kind code; the kinds and paths come from the site.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { refreshIndex } from "~/lib/index.server";
import { action as editorAction, loader as editorLoader } from "~/routes/editor";
import { loader as historyLoader } from "~/routes/history";
import { loader as previewLoader } from "~/routes/preview";
import { loader as projectLoader } from "~/routes/project";

import { addPerson, addProject, resetDb } from "./env";
import { connectedEnv, fakeSite, kindedAdapter, viewerFor } from "./site";

const SLUG = "de-info";
const OWNER = "owner@test.invalid";
let projectId = 0;

beforeEach(async () => {
  await resetDb();
  await addPerson(OWNER, { owner: true });
  projectId = await addProject(SLUG, "dustinedwards");
});

async function contextFor(env: Env) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(OWNER));
  context.set(nonceContext, "test-nonce");
  return context;
}

async function settled<T>(run: () => Promise<T>): Promise<T | Response> {
  try {
    return await run();
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

async function seeded() {
  const site = fakeSite(kindedAdapter());
  vi.stubGlobal("fetch", site.fetch);
  const env = connectedEnv();
  const put = async (id: string, source: string, publish: boolean) => {
    const saved = await site.adapter.content.saveDraft(id, { source, expectedVersion: null, changeId: `seed-${id}` });
    if (publish) await site.adapter.content.publish(id, { expectedVersion: saved.version, changeId: `seed-pub-${id}` });
  };
  await put("a-post", "---\ntitle: A post\n---\nWords.\n", true);
  await put("draft-post", "---\ntitle: A draft post\n---\nNot yet.\n", false);
  await put("phage.acorn15", "---\ntitle: Acorn15\nhost: Gordonia\n---\nA cluster DJ phage.\n", true);
  await put("roster.2017", "---\ntitle: 2017 cohort\nyear: 2017\n---\n", true);
  await put("procedure.coi-primers", "---\ntitle: COI primers\n---\nThe PCR protocol.\n", true);
  await refreshIndex(env, { id: projectId, site: "dustinedwards" });
  return { site, env };
}

const form = (fields: Record<string, string>) => {
  const body = new FormData();
  for (const [k, v] of Object.entries(fields)) body.set(k, v);
  return body;
};

describe("every kind the site reports", () => {
  it("lists each writing kind under its own kind, and the kind filter narrows to it", async () => {
    const { env } = await seeded();
    const context = await contextFor(env);
    const all = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(all.kinds).toEqual(["phage", "post", "procedure", "roster"]);
    const byId = Object.fromEntries(all.items.map((i) => [i.itemId, i]));
    expect(byId["phage.acorn15"]).toMatchObject({ kind: "phage", path: "/research/phages#acorn15", status: "published" });
    expect(byId["roster.2017"]).toMatchObject({ kind: "roster", path: "/teaching/phage-discovery#year-2017" });
    expect(byId["procedure.coi-primers"]).toMatchObject({ kind: "procedure", path: "/research/protocols/coi-primers" });
    expect(byId["draft-post"]).toMatchObject({ kind: "post", status: "draft", path: null });

    const phages = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}?kind=phage`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(phages.items.map((i) => i.itemId)).toEqual(["phage.acorn15"]);
  });

  it("opens, saves, previews, publishes and shows the history of a non-post kind", async () => {
    const { env, site } = await seeded();
    const id = "phage.acorn15";
    const params = { project: SLUG, item: id };
    const url = `https://carrel.test/p/${SLUG}/e/${id}`;

    const opened = (await editorLoader({ request: new Request(url), params, context: await contextFor(env) } as never)) as Awaited<ReturnType<typeof editorLoader>>;
    expect(opened.title).toBe("Acorn15");
    expect(opened.path).toBe("/research/phages#acorn15");
    // Links written in the editor go to each item's own address on the site, a draft post to where the site's posts live.
    expect(opened.linkTargets.map((t) => t.href).sort()).toEqual([
      "/research/protocols/coi-primers",
      "/teaching/phage-discovery#year-2017",
      "/writing/a-post",
      "/writing/draft-post",
    ]);

    const source = "---\ntitle: Acorn15\nhost: Gordonia terrae\n---\nA cluster DJ phage, found in 2015.\n";
    const saved = await editorAction({ request: new Request(url, { method: "POST", body: form({ intent: "save", source, expectedVersion: opened.version! }) }), params, context: await contextFor(env) } as never);
    expect(saved).toMatchObject({ intent: "write", outcome: { ok: true, action: "save", status: "published" } });
    const version = (saved as { outcome: { version: string } }).outcome.version;

    const previewed = (await settled(async () => previewLoader({ request: new Request(`${url}/preview`), params, context: await contextFor(env) } as never))) as Response;
    expect(previewed.status).toBe(200);
    expect(await previewed.text()).toContain("found in 2015");

    const published = await editorAction({ request: new Request(url, { method: "POST", body: form({ intent: "publish", source, expectedVersion: version }) }), params, context: await contextFor(env) } as never);
    expect(published).toMatchObject({ intent: "write", outcome: { ok: true, action: "publish", status: "published" } });
    expect((await site.adapter.content.get(id))?.source).toContain("found in 2015");

    const history = (await historyLoader({ request: new Request(`${url}/history`), params, context: await contextFor(env) } as never)) as { revisions: unknown[] | null };
    expect(history.revisions?.length).toBe(4);
  });

  it("keeps a data kind out of the lists, and shows the site's own refusal if one is written", async () => {
    const { env, site } = await seeded();
    // The site's import puts registry rows in place directly; Carrel never wrote them.
    await env.DB.prepare("INSERT INTO site_items (project_id, item_id, kind, title, status, synced_at) VALUES (?, 'equipment.heat-block', 'equipment', 'Heat block', 'published', '2026-10-10T00:00:00Z')").bind(projectId).run();
    const context = await contextFor(env);
    const listed = (await projectLoader({ request: new Request(`https://carrel.test/p/${SLUG}`), params: { project: SLUG }, context } as never)) as Awaited<ReturnType<typeof projectLoader>>;
    expect(listed.kinds).not.toContain("equipment");
    expect(listed.items.map((i) => i.itemId)).not.toContain("equipment.heat-block");

    const params = { project: SLUG, item: "equipment.heat-block" };
    const written = await editorAction({
      request: new Request(`https://carrel.test/p/${SLUG}/e/equipment.heat-block`, { method: "POST", body: form({ intent: "save", source: "---\nname: Heat block\n---\n", expectedVersion: "" }) }),
      params,
      context: await contextFor(env),
    } as never);
    expect(written).toMatchObject({ intent: "write", outcome: { ok: false, reason: "refused", message: "The site's equipment entries are edited in the site's repository, not through Carrel." } });
    expect(await site.adapter.content.get("equipment.heat-block")).toBeNull();
  });
});

test/google-routes.test.ts.source:
// The Google routes through their loaders: manuscripts and Connect Google are the Owner's, and the
// OAuth round trip runs through the real route with the fake Google behind it.

import { RouterContextProvider } from "react-router";
import { beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { clearSaTokenCache } from "~/lib/google/service-account.server";
import { loader as authLoader } from "~/routes/auth.google";
import { loader as homeLoader } from "~/routes/home";
import { loader as manuscriptsLoader } from "~/routes/manuscripts";

import { addPerson, resetDb, testEnv } from "./env";
import { CODE, fakeGoogle, serviceAccountKey } from "./google";
import { viewerFor } from "./site";

let key: Awaited<ReturnType<typeof serviceAccountKey>>;
beforeAll(async () => {
  key = await serviceAccountKey();
});

let env: Env;
beforeEach(async () => {
  clearSaTokenCache();
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  await addPerson("editor@test.invalid");
  vi.stubGlobal("fetch", fakeGoogle({ publicJwk: key.publicJwk }).fetch);
  env = {
    ...testEnv,
    GOOGLE_SA_KEY: key.json,
    GOOGLE_OAUTH_CLIENT_ID: "id",
    GOOGLE_OAUTH_CLIENT_SECRET: "secret",
    GOOGLE_TOKEN_KEY: btoa(String.fromCharCode(...new Uint8Array(32).fill(7))),
    GOOGLE_MANUSCRIPTS_FOLDER_ID: "folderRoot1",
  } as Env;
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

async function settle<T>(p: Promise<T>): Promise<T | Response> {
  try {
    return await p;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

describe("Google routes", () => {
  it("PLANT: manuscripts and Connect Google are 404 to anyone but the Owner", async () => {
    const req = new Request("https://carrel.test/manuscripts");
    expect(((await settle(manuscriptsLoader({ request: req, params: {}, context: await context("editor@test.invalid") } as never))) as Response).status).toBe(404);
    const start = new Request("https://carrel.test/auth/google/start");
    expect(((await settle(authLoader({ request: start, params: { step: "start" }, context: await context("editor@test.invalid") } as never))) as Response).status).toBe(404);
    const home = (await homeLoader({ request: new Request("https://carrel.test/"), params: {}, context: await context("editor@test.invalid") } as never)) as Awaited<ReturnType<typeof homeLoader>>;
    expect(home.google).toBeNull();
  });

  it("connects Google through the real routes and says so on the home page", async () => {
    const owner = await context("owner@test.invalid");
    const start = (await authLoader({ request: new Request("https://carrel.test/auth/google/start"), params: { step: "start" }, context: owner } as never)) as Response;
    const google = new URL(start.headers.get("Location")!);
    expect(google.hostname).toBe("accounts.google.com");
    const back = new Request(`https://carrel.test/auth/google/callback?state=${google.searchParams.get("state")}&code=${encodeURIComponent(CODE)}`);
    const done = (await authLoader({ request: back, params: { step: "callback" }, context: await context("owner@test.invalid") } as never)) as Response;
    const message = new URL(done.headers.get("Location")!, "https://carrel.test").searchParams.get("google");
    expect(message).toBe("Google is connected for Send to Docs and Import (drive.file only).");
    const home = (await homeLoader({ request: new Request("https://carrel.test/"), params: {}, context: await context("owner@test.invalid") } as never)) as Awaited<ReturnType<typeof homeLoader>>;
    expect(home.google).toEqual({ configured: true, connected: true });
  });

  it("shows the manuscripts page with the setup still missing, rather than failing", async () => {
    env = { ...env, GOOGLE_SA_KEY: undefined } as Env;
    const data = (await manuscriptsLoader({ request: new Request("https://carrel.test/manuscripts?q=x"), params: {}, context: await context("owner@test.invalid") } as never)) as Awaited<
      ReturnType<typeof manuscriptsLoader>
    >;
    expect(data.setup).toMatch(/^GOOGLE_SA_KEY is not set/);
    expect(data.files).toEqual([]);
  });
});

test/mcp-followups.test.ts.source:
// The follow-ups after the overnight merges: books through MCP, draft_social_post, a reviewer's flag
// that a recheck must not withdraw, and export refused while an import marker is left in a book.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { exportGate, listFindings, refreshBook, requireBookProject, saveBookFile, type BookProject } from "~/lib/books.server";
import { autosave, readDraft } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import type { Viewer } from "~/lib/people.server";
import { createAccount, recordPublication, setSwitches } from "~/lib/social/queue.server";
import { action as fileAction, loader as fileLoader } from "~/routes/book.file";

import { addBook, addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectAs } from "./mcp-client";
import { fakeNovels } from "./novels";
import { viewerFor } from "./site";

const SLUG = "test-book";
const HEADER = "---\npov: Wade\ndate: 2024-04-12\nlocation: Harlan place\ncharacters: [Wade]\ngoal: g\nconflict: c\noutcome: o\n---\n\n";
const SCENE = "chapters/01-arrival/01-the-gate.md";

let gh: ReturnType<typeof fakeNovels>;

async function readDraftOnly(project: BookProject, viewer: Viewer, path: string) {
  return (await readDraft(testEnv.DB, project, viewer, path))?.source;
}

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  const reviewer = await addPerson("reviewer@test.invalid", { reviewer: true });
  const id = await addBook(SLUG);
  await share(id, editor, "editor");
  await share(id, reader, "reader");
  await share(id, reviewer, "reader");
  gh = fakeNovels({
    [`${SLUG}/bible/characters/wade.md`]: "---\nname: Wade\n---\n",
    [`${SLUG}/bible/places/harlan-place.md`]: "---\nname: Harlan place\n---\n",
    [`${SLUG}/${SCENE}`]: `${HEADER}Wade opened the gate.\n`,
  });
  const owner = await viewerFor("owner@test.invalid");
  await refreshBook(testEnv.DB, gh.repo, await requireBookProject(testEnv.DB, owner, SLUG, "read"));
});

async function connect(email: string, client = "Claude") {
  const ai = await connectAs(email, client);
  return ai.call;
}

describe("books through MCP", () => {
  it("lists a book's files with each scene's header, and reads a file with its version", async () => {
    const call = await connect("reader@test.invalid");
    const list = await call("list_book_files", { project: SLUG });
    expect(list.structuredContent).toMatchObject({ files: expect.arrayContaining([{ path: SCENE, kind: "scene", words: 4, header: expect.objectContaining({ pov: "Wade" }), openFlags: 0 }]) });
    const read = await call("read_book_file", { project: SLUG, path: SCENE });
    expect(read.structuredContent).toMatchObject({ path: SCENE, source: `${HEADER}Wade opened the gate.\n`, version: gh.files.get(`${SLUG}/${SCENE}`)!.sha });
  });

  it("PLANT: a stranger's session, and a site's slug, reach no book", async () => {
    await addPerson("stranger@test.invalid");
    expect(await (await connect("stranger@test.invalid"))("list_book_files", { project: SLUG })).toMatchObject({ isError: true });
    await addProject("a-site", "dustinedwards");
    expect(await (await connect("owner@test.invalid"))("list_book_files", { project: "a-site" })).toMatchObject({ isError: true });
  });

  it("runs the checks on text without saving or recording anything", async () => {
    const call = await connect("reader@test.invalid");
    const result = await call("check_book_text", { project: SLUG, path: SCENE, source: `${HEADER}A tapestry.\n` });
    expect(result.structuredContent).toMatchObject({ findings: [{ check: "ai-habits", excerpt: "tapestry" }] });
    const owner = await viewerFor("owner@test.invalid");
    expect(await listFindings(testEnv.DB, await requireBookProject(testEnv.DB, owner, SLUG, "read"))).toEqual([]);
  });

  it("saves an AI draft beside the person's, never over it and never to Git", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireBookProject(testEnv.DB, owner, SLUG, "read");
    await autosave(testEnv.DB, project, owner, SCENE, { source: "Dustin's own draft.", baseVersion: null });

    const saved = await (await connect("owner@test.invalid"))("save_book_draft", { project: SLUG, path: SCENE, source: `${HEADER}An AI version.\n`, note: "Tighter." });
    expect(saved.structuredContent).toMatchObject({ saved: true, basedOnVersion: gh.files.get(`${SLUG}/${SCENE}`)!.sha });
    expect(await readDraftOnly(project, owner, SCENE)).toBe("Dustin's own draft.");
    expect(gh.commits).toEqual([]);
  });

  it("PLANT: a reviewer's and a Reader's sessions cannot save a book draft", async () => {
    expect(await (await connect("reviewer@test.invalid"))("save_book_draft", { project: SLUG, path: SCENE, source: "x" })).toMatchObject({
      isError: true,
      content: [{ text: "A reviewer flags; it does not write text. Use add_book_finding." }],
    });
    expect(await (await connect("reader@test.invalid"))("save_book_draft", { project: SLUG, path: SCENE, source: "x" })).toMatchObject({ isError: true });
  });

  it("PLANT: a reviewer's flag on a book file survives the recheck a save runs, and holds export", async () => {
    const reviewer = await connect("reviewer@test.invalid", "Grok Build");
    const flagged = await reviewer("add_book_finding", { project: SLUG, path: SCENE, message: "Wade could not see the gate from the road.", excerpt: "opened the gate" });
    expect(flagged.structuredContent).toMatchObject({ flagged: true, alreadyFlagged: false });

    const owner = await viewerFor("owner@test.invalid");
    const project = await requireBookProject(testEnv.DB, owner, SLUG, "publish");
    const current = gh.files.get(`${SLUG}/${SCENE}`)!;
    const saved = await saveBookFile(testEnv.DB, gh.repo, project, owner, SCENE, { source: `${HEADER}Wade opened the old gate.\n`, expectedVersion: current.sha });
    expect(saved.ok).toBe(true);
    expect((await listFindings(testEnv.DB, project, { path: SCENE })).map((f) => [f.check, f.status])).toEqual([["review", "open"]]);
    expect(await exportGate(testEnv.DB, project)).toMatchObject({ ok: false, open: 1 });
  });

  it("PLANT: a flag on a path outside the layout is refused", async () => {
    expect(await (await connect("reviewer@test.invalid"))("add_book_finding", { project: SLUG, path: "../x.md", message: "m" })).toMatchObject({ isError: true });
  });
});

describe("AI drafts in the book editor", () => {
  it("shows them beside the text, and Use as my draft makes one the working copy", async () => {
    await (await connect("owner@test.invalid"))("save_book_draft", { project: SLUG, path: SCENE, source: `${HEADER}An AI version.\n` });
    vi.stubGlobal("fetch", gh.fetch);
    const context = new RouterContextProvider();
    context.set(cloudflareContext, { env: testEnv, ctx: {} as ExecutionContext });
    context.set(viewerContext, await viewerFor("owner@test.invalid"));
    context.set(nonceContext, "n");
    const params = { project: SLUG, "*": SCENE };
    const data = (await fileLoader({ request: new Request("https://carrel.test/"), params, context } as never)) as Awaited<ReturnType<typeof fileLoader>>;
    expect(data.aiDrafts).toMatchObject([{ client: "Claude", source: `${HEADER}An AI version.\n` }]);

    const body = new FormData();
    body.set("intent", "use-ai-draft");
    body.set("draft", String(data.aiDrafts[0]!.id));
    expect(await fileAction({ request: new Request("https://carrel.test/", { method: "POST", body }), params, context } as never)).toEqual({ intent: "use-ai-draft", used: data.aiDrafts[0]!.id });
    const owner = await viewerFor("owner@test.invalid");
    expect(await readDraftOnly(await requireBookProject(testEnv.DB, owner, SLUG, "read"), owner, SCENE)).toBe(`${HEADER}An AI version.\n`);
  });
});

describe("export refuses a book with import markers", () => {
  it("PLANT: names each file still holding a marker; clean, it passes", async () => {
    await gh.commitElsewhere(`${SLUG}/chapters/01-arrival/02-letter.md`, `${HEADER}Before.\n\n<!-- import: table: A table was not converted. -->\n\nAfter.\n`);
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireBookProject(testEnv.DB, owner, SLUG, "publish");
    await refreshBook(testEnv.DB, gh.repo, project);
    const held = await exportGate(testEnv.DB, project);
    expect(held).toMatchObject({ ok: false });
    expect(held.ok || held.message).toBe(
      "1 file still holds an <!-- import: ... --> marker from the Word import: chapters/01-arrival/02-letter.md. Fix the text there and delete each marker before exporting.",
    );
    await gh.commitElsewhere(`${SLUG}/chapters/01-arrival/02-letter.md`, `${HEADER}Before.\n\nAfter.\n`);
    await refreshBook(testEnv.DB, gh.repo, project);
    expect(await exportGate(testEnv.DB, project)).toEqual({ ok: true });
  });
});

describe("draft_social_post", () => {
  async function socialAccount() {
    const projectId = await addProject("germomics", "dustinedwards");
    const owner = await viewerFor("owner@test.invalid");
    await createAccount(testEnv.DB, owner, { key: "germomics-bluesky", name: "Germomics", platform: "bluesky", kind: "brand", handle: "g.bsky.social", projectId });
    const row = await testEnv.DB.prepare("SELECT id FROM social_accounts").first<{ id: number }>();
    await setSwitches(testEnv.DB, owner, row!.id, { enabled: true });
    await recordPublication(testEnv.DB, projectId, { id: "ep-1", title: "Episode 1", url: "https://site.test/ep-1", summary: "" });
    return (await testEnv.DB.prepare("SELECT id FROM social_events").first<{ id: number }>())!.id;
  }

  it("stores the Owner's session's draft by event id, credited to the client", async () => {
    const eventId = await socialAccount();
    const result = await (await connect("owner@test.invalid", "Claude Code"))("draft_social_post", { event_id: eventId, text: "Episode 1 is out: https://site.test/ep-1" });
    expect(result.structuredContent).toMatchObject({ stored: true });
    expect(await testEnv.DB.prepare("SELECT source, status, created_by FROM social_posts").first()).toEqual({ source: "predrafted", status: "drafted", created_by: "Claude Code" });
  });

  it("stores by account, project and item too", async () => {
    await socialAccount();
    const result = await (await connect("owner@test.invalid"))("draft_social_post", { account: "germomics-bluesky", project: "germomics", item: "ep-2", text: "Episode 2." });
    expect(result.structuredContent).toMatchObject({ stored: true });
  });

  it("PLANT: an Editor's or a reviewer's session cannot draft social posts", async () => {
    const eventId = await socialAccount();
    for (const email of ["editor@test.invalid", "reviewer@test.invalid"]) {
      expect(await (await connect(email))("draft_social_post", { event_id: eventId, text: "x" })).toMatchObject({
        isError: true,
        content: [{ text: "Social posts are Dustin's: only his own sessions may draft them." }],
      });
    }
    expect(await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM social_posts").first()).toEqual({ n: 0 });
  });
});

test/mcp.test.ts.source:
// The MCP endpoint and its tools, as an AI client meets them: the protocol in both eras, the tools
// over posts, and the planted refusals from design decision 2 (a shared user's session publishing, a
// reviewer publishing, an Owner's publish with an open flag). The site is site-api's own handler over
// its reference adapter; the email binding is a mailbox the tests read. The session is what the door
// hands over from the OAuth grant: the person and the client, credited by the client's name.

import { beforeEach, describe, expect, it } from "vitest";

import { autosave, readDraft } from "~/lib/content.server";
import { runHealth } from "~/lib/health.server";
import { requireSiteProject } from "~/lib/projects.server";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectAs, legacyRequest, LEGACY, MCP_HOST, MCP_URL, modernRequest, readMessage } from "./mcp-client";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
const CARREL = "https://carrel.test";

type Sent = { from: string; to: string; subject: string; text: string };

function mailbox(fail = false) {
  const sent: Sent[] = [];
  const EMAIL = {
    async send(message: Sent) {
      if (fail) throw new Error("send failed");
      sent.push(message);
      return { messageId: `m${sent.length}` };
    },
  } as unknown as SendEmail;
  return { sent, EMAIL };
}

let site: ReturnType<typeof fakeSite>;
let box: ReturnType<typeof mailbox>;
let env: Env;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  const reviewer = await addPerson("reviewer@test.invalid", { reviewer: true });
  await addPerson("stranger@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  await share(id, reader, "reader");
  await share(id, reviewer, "reader");
  site = fakeSite();
  box = mailbox();
  env = { ...connectedEnv(), EMAIL: box.EMAIL };
});

async function connect(email: string, client = "Claude", e: Env = env) {
  return connectAs(email, client, { env: e, deps: { fetcher: site.fetch, carrelOrigin: CARREL } });
}

/** A post the Owner saved on the site through the buttons' own function, returned with its version. */
async function seedPost(status: "draft" | "published" = "draft") {
  const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Post one\n---\nDustin's words.\n", expectedVersion: null, changeId: "seed" });
  if (status === "draft") return saved.version;
  return (await site.adapter.content.publish("post-one", { expectedVersion: saved.version, changeId: "seed-publish" })).version;
}

describe("the protocol", () => {
  it("lists the tools in the 2026-07-28 era, each carrying the rule", async () => {
    const tools = await (await connect("owner@test.invalid")).list();
    expect(tools.map((t) => t.name)).toEqual(["list_projects", "search_items", "read_item", "save_draft", "preview", "get_checks", "add_finding", "publish", "list_book_files", "read_book_file", "check_book_text", "save_book_draft", "add_book_finding", "draft_social_post"]);
    for (const tool of tools) expect(tool.description).toContain("AI never rewrites Dustin's prose unasked.");
  });

  it("answers a 2025-era client through the legacy shim: initialize, then calls with no session", async () => {
    const ai = await connect("reader@test.invalid");
    const init = await readMessage(
      await ai.send(legacyRequest({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: LEGACY, capabilities: {}, clientInfo: { name: "Claude Code", version: "2.1" } } })),
    );
    expect(init.result).toMatchObject({ protocolVersion: LEGACY, serverInfo: { name: "carrel" }, capabilities: { tools: {} } });
    const legacy = await connectAs("reader@test.invalid", "Claude", { env, deps: { fetcher: site.fetch, carrelOrigin: CARREL }, era: "legacy" });
    expect((await legacy.list()).length).toBe(14);
    expect((await legacy.call("list_projects")).structuredContent).toMatchObject({ projects: [{ slug: SLUG, role: "reader" }] });
  });

  it("answers an unknown protocol version at initialize with one it speaks", async () => {
    const ai = await connect("owner@test.invalid");
    const init = await readMessage(await ai.send(legacyRequest({ jsonrpc: "2.0", id: 1, method: "initialize", params: { protocolVersion: "1999-01-01", capabilities: {}, clientInfo: { name: "x", version: "1" } } })));
    expect(["2025-11-25", "2025-06-18", "2025-03-26"]).toContain(init.result?.protocolVersion);
  });

  it("PLANT: a page elsewhere cannot drive the tools, a rebinding host is refused, and GET, DELETE, 2026-era batches and bad JSON are refused", async () => {
    const ai = await connect("owner@test.invalid");
    expect((await ai.send(modernRequest(2, "tools/list", {}, { Origin: "https://evil.example" }))).status).toBe(403);
    expect((await ai.send(modernRequest(2, "tools/list", {}, { Host: "evil.example" }))).status).toBe(403);
    expect((await ai.send(new Request(MCP_URL, { headers: { Host: MCP_HOST, Accept: "text/event-stream" } }))).status).toBe(405);
    expect((await ai.send(new Request(MCP_URL, { method: "DELETE", headers: { Host: MCP_HOST } }))).status).toBe(405);
    const one = modernRequest(1, "tools/list");
    const body = [JSON.parse(await one.clone().text()), JSON.parse(await one.clone().text())];
    const batch = await ai.send(new Request(one, { body: JSON.stringify(body) }));
    // Refused in the design-center era. The legacy shim answers 2025-era batches as that era allowed;
    // each message in one still runs as this same session, so a batch widens nothing.
    expect(batch.status).toBe(400);
    const bad = new Request(MCP_URL, { method: "POST", body: "{not json", headers: { Host: MCP_HOST, "Content-Type": "application/json", Accept: "application/json, text/event-stream" } });
    expect((await ai.send(bad)).status).toBe(400);
  });
});

describe("reading, drafting, flagging", () => {
  it("lists projects, searches and reads posts through the buttons' own functions", async () => {
    await seedPost();
    const ai = await connect("reader@test.invalid");
    expect((await ai.call("list_projects")).structuredContent).toMatchObject({ projects: [{ slug: SLUG, role: "reader" }] });
    const read = await ai.call("read_item", { project: SLUG, item: "post-one" });
    expect(read.isError).toBeUndefined();
    expect(read.structuredContent).toMatchObject({ site: { id: "post-one", title: "Post one" }, dustinsDraft: null, aiDrafts: [], flags: [] });
  });

  it("PLANT: a stranger's session reads nothing", async () => {
    const ai = await connect("stranger@test.invalid");
    const result = await ai.call("read_item", { project: SLUG, item: "post-one" });
    expect(result).toMatchObject({ isError: true, content: [{ text: "Not found, or not shared with this person." }] });
  });

  it("saves an AI draft beside Dustin's, never over his draft or the site's text", async () => {
    const version = await seedPost();
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireSiteProject(testEnv.DB, owner, SLUG, "read");
    await autosave(testEnv.DB, project, owner, "post-one", { source: "Dustin's working draft.", baseVersion: version });

    const ai = await connect("owner@test.invalid");
    const saved = await ai.call("save_draft", { project: SLUG, item: "post-one", source: "An AI rewrite.", note: "Tightened the opening." });
    expect(saved.structuredContent).toMatchObject({ saved: true, basedOnVersion: version });
    expect((await readDraft(testEnv.DB, project, owner, "post-one"))?.source).toBe("Dustin's working draft.");
    expect((await site.adapter.content.get("post-one"))?.source).toBe("---\ntitle: Post one\n---\nDustin's words.\n");
    expect(site.requests.filter((r) => !r.startsWith("GET"))).toEqual([]);
    const read = await ai.call("read_item", { project: SLUG, item: "post-one" });
    expect(read.structuredContent).toMatchObject({ aiDrafts: [{ client: "Claude", note: "Tightened the opening." }] });
  });

  it("PLANT: a Reader's session and a reviewer's cannot save a draft", async () => {
    await seedPost();
    expect(await (await connect("reader@test.invalid")).call("save_draft", { project: SLUG, item: "post-one", source: "x" })).toMatchObject({
      isError: true,
      content: [{ text: "You may not write drafts on this project." }],
    });
    expect(await (await connect("reviewer@test.invalid")).call("save_draft", { project: SLUG, item: "post-one", source: "x" })).toMatchObject({
      isError: true,
      content: [{ text: "A reviewer flags; it does not write text. Use add_finding." }],
    });
  });

  it("lets a reviewer flag, once per flag, credited to its client", async () => {
    await seedPost();
    const reviewer = await connect("reviewer@test.invalid", "Grok Build");
    const args = { project: SLUG, item: "post-one", message: "This number has no source.", excerpt: "Dustin's words." };
    expect((await reviewer.call("add_finding", args)).structuredContent).toMatchObject({ flagged: true, alreadyFlagged: false });
    expect((await reviewer.call("add_finding", args)).structuredContent).toMatchObject({ alreadyFlagged: true });
    const checks = await (await connect("owner@test.invalid")).call("get_checks", { project: SLUG, item: "post-one" });
    expect(checks.structuredContent).toMatchObject({ open: 1, flags: [{ check: "review", message: "This number has no source. (from Grok Build)" }] });
  });

  it("previews through the site's own renderer", async () => {
    await seedPost();
    const result = await (await connect("reader@test.invalid")).call("preview", { project: SLUG, item: "post-one", source: "---\ntitle: T\n---\nHello." });
    expect(result.isError).toBeUndefined();
    expect(String(result.structuredContent?.html)).toContain("Hello.");
  });
});

describe("publish by instruction (decision 2)", () => {
  it("PLANT: a shared user's session publishing is refused, and the site and inbox hear nothing", async () => {
    const version = await seedPost();
    const result = await (await connect("editor@test.invalid")).call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect(result).toMatchObject({ isError: true, content: [{ text: "Only the Owner's own sessions may publish." }] });
    expect((await site.adapter.content.get("post-one"))?.status).toBe("draft");
    expect(site.requests.filter((r) => !r.startsWith("GET"))).toEqual([]);
    expect(box.sent).toEqual([]);
  });

  it("PLANT: a reviewer publishing is refused", async () => {
    const version = await seedPost();
    const result = await (await connect("reviewer@test.invalid")).call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect(result).toMatchObject({ isError: true, content: [{ text: "A reviewer never publishes." }] });
    expect((await site.adapter.content.get("post-one"))?.status).toBe("draft");
  });

  it("PLANT: the Owner's AI publish with an open flag is refused, naming the flag", async () => {
    const version = await seedPost();
    await (await connect("reviewer@test.invalid", "Grok Build")).call("add_finding", { project: SLUG, item: "post-one", message: "Unsourced claim." });
    const result = await (await connect("owner@test.invalid")).call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect(result.isError).toBe(true);
    expect(result.content[0]!.text).toBe(
      "Publish is refused while 1 flag is open on this post: Unsourced claim. (from Grok Build) Dustin fixes the text or dismisses each flag in Carrel first.",
    );
    expect((await site.adapter.content.get("post-one"))?.status).toBe("draft");
    expect(box.sent).toEqual([]);
  });

  it("the Owner's AI publish with clean checks publishes, credits the client, and emails Dustin an unpublish link", async () => {
    const version = await seedPost();
    const result = await (await connect("owner@test.invalid", "Claude")).call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect(result.structuredContent).toMatchObject({ published: true, dustinEmailed: true });
    expect((await site.adapter.content.get("post-one"))?.status).toBe("published");

    const change = await testEnv.DB.prepare("SELECT action, client FROM changes WHERE item_id = 'post-one'").first();
    expect(change).toEqual({ action: "publish", client: "Claude" });
    const record = await testEnv.DB.prepare("SELECT client, emailed_at, email_error FROM ai_publications").first<{ client: string; emailed_at: string | null; email_error: string | null }>();
    expect(record).toMatchObject({ client: "Claude", email_error: null });
    expect(record!.emailed_at).not.toBeNull();

    expect(box.sent).toHaveLength(1);
    expect(box.sent[0]).toMatchObject({ to: "owner@test.invalid", subject: 'Carrel: Claude published "Post one"' });
    expect(box.sent[0]!.text).toContain("Published by Claude on Dustin's instruction.");
    expect(box.sent[0]!.text).toContain(`Unpublish it: ${CARREL}/p/${SLUG}/e/post-one/unpublish`);
  });

  it("PLANT: publish sends no text, so an AI draft can never be what goes live", async () => {
    const version = await seedPost();
    const ai = await connect("owner@test.invalid");
    await ai.call("save_draft", { project: SLUG, item: "post-one", source: "---\ntitle: Post one\n---\nAI words.\n" });
    await ai.call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect((await site.adapter.content.get("post-one"))?.source).toBe("---\ntitle: Post one\n---\nDustin's words.\n");
  });

  it("PLANT: a stale expected version is refused by the site", async () => {
    await seedPost();
    const result = await (await connect("owner@test.invalid")).call("publish", { project: SLUG, item: "post-one", expected_version: "stale" });
    expect(result.isError).toBe(true);
    expect((await site.adapter.content.get("post-one"))?.status).toBe("draft");
  });

  it("keeps the publish when the email fails, records why, and the health check reports it", async () => {
    const version = await seedPost();
    const failing = mailbox(true);
    const e = { ...env, EMAIL: failing.EMAIL };
    const result = await (await connect("owner@test.invalid", "Claude", e)).call("publish", { project: SLUG, item: "post-one", expected_version: version });
    expect(result.structuredContent).toMatchObject({ published: true, dustinEmailed: false });

    const health = mailbox();
    const { results } = await runHealth({ ...testEnv, EMAIL: health.EMAIL }, async () => Response.json({ keys: [{ kid: "k" }] }));
    expect(results.find((r) => r.name === "ai-publish-email")).toMatchObject({ ok: false, detail: "1 AI publish was not emailed: post-one by Claude (send failed)." });
  });
});

